import React, { useState } from 'react';
import { useOutletContext, Outlet, useLocation } from 'react-router-dom';
import ProjectNavbar from '../../components/ProjectNavbar';
import '../../components/RealtimeWorkspace.css'; 

const InsuranceModule = () => {
  const context = useOutletContext();
  const location = useLocation();
  const isSubPage = location.pathname.includes('/p');

  const [question, setQuestion] = useState('');
  const [loading, setLoading] = useState(false);
  const [answer, setAnswer] = useState(context?.ins?.data || null);

  const moduleContext = { 
    ...context, 
    ins: { data: answer, setter: setAnswer } 
  };

  const handleQuery = async () => {
    setLoading(true);
    try {
      const response = await fetch('http://localhost:8000/api/insurance/query', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text: question }),
      });
      const data = await response.json();
      setAnswer(data);
      if (context?.ins?.setter) context.ins.setter(data);
    } catch (error) {
      console.error("Query failed:", error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="workspace-container">
      <ProjectNavbar basePath="ins" links={["Claims", "Risk", "Policies", "Ledger"]} />
      
      {isSubPage ? (
        <Outlet context={moduleContext} />
      ) : (
        <div className="dashboard-content">
          <div className="metrics-grid">
            <div className="metric-card"><p>POLICY MATCH</p><h4>{answer?.score || 94}%</h4></div>
            <div className="metric-card"><p>LATENCY</p><h4>{answer?.latency || 45}ms</h4></div>
            <div className="metric-card"><p>STATUS</p><h4 style={{color:'#22c55e'}}>● Secure</h4></div>
          </div>
          <div className="input-section">
            <textarea className="workspace-textarea" placeholder="Ask about policy coverage..." value={question} onChange={(e) => setQuestion(e.target.value)} />
            <button className="workspace-button" onClick={handleQuery} disabled={loading}>{loading ? 'Processing...' : 'Query AI Engine'}</button>
          </div>
        </div>
      )}
    </div>
  );
};
export default InsuranceModule;
